import java.nio.file.*;import java.io.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Read-only inventory for the still-open common Ref scene/owner consumers. */
public final class CompanionRefConsumerCensus {
 public static void main(String[]args)throws Exception{try(var jar=new JarFile(args[0]);var out=Files.newBufferedWriter(Path.of(args[1]))){out.write("class\tmethod\tcallee\n");for(var e:Collections.list(jar.entries())){if(!e.getName().endsWith(".class"))continue;var c=new ClassNode();new ClassReader(jar.getInputStream(e)).accept(c,ClassReader.SKIP_DEBUG);for(var m:c.methods)for(var n:m.instructions)if(n instanceof MethodInsnNode v&&(v.owner.equals("local/lito381/server/NativeCombatAttacker$Ref")&&Set.of("map","instance","room","master","owner","<init>").contains(v.name)||v.owner.equals("local/lito381/server/NativeCombatAttacker")&&Set.of("live","alive","scene","companion").contains(v.name)))out.write(c.name+"\t"+m.name+m.desc+"\t"+v.owner+"."+v.name+v.desc+"\n");else if(n instanceof FieldInsnNode f&&f.owner.equals("local/lito381/server/NativeCombatAttacker$Ref"))out.write(c.name+"\t"+m.name+m.desc+"\tFIELD "+f.owner+"."+f.name+" "+f.desc+"\n");}}}
}
